0,"Create a Python function that processes a text file containing comma-separated values (CSV) and outputs a formatted report. The function should accept three parameters: the name of the input CSV file, the name of the output report file, and a string specifying column aggregation rules. The function should use standard library functions and dynamically allocate memory. The output report should present aggregated data based on the provided rules, including calculations like sum, average, or count for specified columns.",120,,"[""```python
import csv
from collections import defaultdict

def process_csv(input_file, output_file, aggregation_rules):
    input_data = []
    with open(input_file, 'r') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            input_data.append(row)

    # Parse aggregation rules
    rules = {}
    for key, value in map(lambda x: x.split(':'), aggregation_rules.split(',')):
        rules[key] = {v.strip() for v in value.split(' ')}

    agg_functions = {'sum': sum, 'count': len, 'average': lambda lst: sum(lst) / len(lst)}

    # Aggregate and format output data
    output = []
    for column in input_data[0]:
        if column in rules:
            grouped_data = defaultdict(lambda: [{}])
            for row in input_data:
                grouped_data[row[column]][row]['count'] += 1
                for agg_type, value in map(lambda x: (x[0], agg_functions[x[1]](row[x[2]])), rules[column]):
                    grouped_data[row[column]][row][agg_type] = value

            for key, group in grouped_data.items():
                row = {'Column': column}
                for agg_type, values in group.items():
                    row[agg_type] = values[0]['count'], values[0].get(agg_type), sum([v[agg_type] for v in values.values() if agg_type != 'count'])
                output.append(row)

    # Write to the output file
    with open(output_file, 'w', newline='') as csvfile:
        fieldnames = ['Column'] + list(rules.keys())
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for row in output:
            writer.writerow(row)

```
