0,"Write a program in Python that defines a class for managing a stack data structure. The class should have methods for pushing, popping, and checking if the stack is empty. Additionally, implement a method to calculate the average of all elements in the stack and another method to remove duplicate elements from the stack.",377,,"['```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def is_empty(self):
        return len(self.items) == 0

    def average(self):
        total = sum(self.items)
        return total / len(self.items) if self.items else None

    def remove_duplicates(self):
        new_stack = Stack()
        unique_elements = set()

        for item in self.items:
            if item not in unique_elements:
                new_stack.push(item)
                unique_elements.add(item)

        self.items = [item for item in new_stack.items]
