class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()

    def is_empty(self):
        return len(self.items) == 0

    def average(self):
        total = sum(self.items, 0) / len(self.items)
        return total

    def remove_duplicates(self):
        self.items = list(dict.fromkeys(self.items))
