import random
import string

def generate_phone_number(name, area_code):
    characters = string.digits + string.ascii_uppercase
    suffix = ''.join(random.choice(characters) for _ in range(7))
    full_phone = area_code + '-' + name[:3].upper() + suffix
    return full_phone

# Example usage: generate a unique phone number for a patient named ""John Doe"" with an area code of 123
