def generate_fib(lst):
    fib = {0: 0, 1: 1}
    max_val = max(lst)

    while True:
        next_fib = fib[max_val - 2] + fib[max_val - 1] if (max_val - 2) in fib and (max_val - 1) in fib else max_val
        fib[next_fib] = next_fib
        max_val = next_fib
        yield next_fib

def fibonacci_set(lst, reverse=False):
    set_gen = (value for value in generate_fib(lst) if value <= max(lst))
    return list(reversed(set_gen)) if reverse else list(set_gen)
