import threading
import queue

class ProcessResult:
    def __init__(self, pid, status, output):
        self.pid = pid
        self.status = status
        self.output = output

class Command:
    def __init__(self, command, options=None):
        self.command = command
        self.options = options or {}

    def execute(self):
        pass

class SubprocessManager:
    def __init__(self, max_concurrent=5, log_level=logging.INFO, **kwargs):
        self.max_concurrent = max_concurrent
        self.commands = queue.Queue()
        self.results = queue.Queue()
        self.lock = threading.Lock()
        self.running_processes = 0
        self._setup_logger(log_level)
        self._kwargs = kwargs

    def _setup_logger(self, log_level):
        logging.basicConfig(level=log_level, format='%(asctime)s - %(name)s - %(levelname)s: %(message)s')

    def add_command(self, command: Command):
        self.commands.put((command, time.time()))

    def start(self):
        with self.lock:
            if self.running_processes >= self.max_concurrent and not self.commands.empty():
                return
        executor = ThreadPoolExecutor(max_workers=self.max_concurrent)
        completed_futures = []
        while True:
            if self.commands.empty():
                break
            command, start_time = self.commands.get()
            future = executor.submit(self._execute_command, command)
            completed_futures.append(future)
        futures = as_completed(completed_futures)
        for future in futures:
            result = future.result()
            self.results.put((result, time.time()))

    def _execute_command(self, command):
        try:
            process = command.execute()
            self._log_process(process, 'start')
            self._track_running_processes(True)
            output, exit_code = process.communicate()
            self._track_output(command, output)
            status = ProcessResult(process.pid, exit_code, output)
            self._log_process(status, 'finish')
            self._track_running_processes(False)
            return status
        except Exception as e:
            self._log_exception(e)
            self._track_running_processes(False)
            raise e

    def _track_output(self, command, output):
        if output:
            print(f'Command {command.command}: Output - {output.decode(""utf-8"")}')

    def _log_process(self, process, event):
        if isinstance(process, BaseException):
            self._log_exception(process)
        else:
            if event == 'start':
                self.log.info(f'Command {process.command} started')
            elif event == 'finish':
                status = f""success"" if process.status == 0 else ""failure""
                self.log.info(f'Command {process.command}: Status - {status}, PID - {process.pid}')

    def _log_exception(self, exception):
        self.log.error(f'Exception in command execution: {exception}', exc_info=True)

    def _track_running_processes(self, add=True):
        with self.lock:
            if add:
                self.running_processes += 1
            else:
                self.running_processes -= 1

    def terminate_all(self, timeout=5):
        signal.signal(signal.SIGTERM, lambda sig, frame: self._terminate(timeout))
        for process in [p for p in self._get_active_processes() if p is not None]:
            process.send_signal(signal.SIGTERM)
        time.sleep(timeout)

    def _terminate(self, timeout):
        signal.alarm(timeout)
        try:
            while True:
                self._get_active_processes()
                time.sleep(0.1)
        finally:
            signal.alarm(0)

    def _get_active_processes(self):
        with self.lock:
            running = [p for p in os.listdir('/proc') if p.isnumeric() and int(p) not in {pid for pid, _, _ in self._results.queue]}
            return [os.path.join('/proc', str(pid)) for pid in running]

