def sum_of_primes(n):
    if not isinstance(n, int):
        raise ValueError(""Input must be an integer."")
    primes = [2]
    num_to_check = 3
    while num_to_check <= n:
        is_prime = True
        for p in primes:
            if num_to_check % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num_to_check)
        num_to_check += 1
    return sum(primes[:n+1])
