```python
def fib_set(lst, reverse=False):
    fib_nums = set()
    a, b = 0, 1

    for i in lst:
        while a <= i:
            fib_nums.add(a)
            a, b = b, a + b

    if reverse:
        return list(reversed(sorted(fib_nums)))
    else:
        return sorted(fib_nums)
```

