   import os
   import hashlib
   import time
   from threading import Lock
   from typing import List, Tuple

   class FileUploadCache:
       def __init__(self, cache_dir: str = None):
           self.cache_dir = cache_dir if cache_dir else 'app_data/cache'
           self.version_dir = os.path.join(self.cache_dir, 'versions')
           self.user_dirs_lock = Lock()
           self.file_locks = {}
           self.user_directories: dict[str, str] = {}
           self.file_versions: dict[str, int] = {}
           self.expiry_times: dict[str, int] = {}

       def set_cache_location(self, new_cache_dir: str):
           with self.user_dirs_lock:
               if new_cache_dir and os.path.exists(new_cache_dir):
                   self.cache_dir = new_cache_dir
                   self.version_dir = os.path.join(self.cache_dir, 'versions')

       def _create_user_directory(self, user_id: str):
           with self.user_dirs_lock:
               if user_id not in self.user_directories:
                   user_directory_path = os.path.join(self.cache_dir, f'user_{user_id}')
                   os.makedirs(user_directory_path)
                   os.chmod(user_directory_path, 0o700)
                   self.user_directories[user_id] = user_directory_path

       def _create_file_version(self, file_path: str) -> int:
           file_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
           version_number = 1 if file_hash not in self.file_versions else (self.file_versions[file_hash] + 1)
           version_file_path = os.path.join(self.version_dir, f'{file_hash}_{version_number}.txt')
           with open(version_file_path, 'w') as version_file:
               version_file.write(file_hash)
               version_file.flush()
               os.fsync(version_file.fileno())
               return version_number

       def _update_expiry_time(self, file_path: str):
           expiry_time_seconds_from_now = time.time() + 86400 # default expiry after 24 hours in seconds
           if file_path not in self.expiry_times:
               open(file_path + '.expiry', 'a').close()  # create an empty expiry time for the file initially to trigger deletion at next check-in or update
               expiry_time_seconds_from_now += (86400 * 365) # add another year's worth of expiry time
