def fib_finder(lst, sorted=False):
    fib = [0, 1]
    up_to = max(lst)
    fibs = []

    for i in range(2, up_to+1):
        fib.append(fib[i-1] + fib[i-2])

    for n in fib:
        if n <= up_to and n not in fibs:
            fibs.append(n)

    if sorted:
        return sorted(fibs, reverse=True)
    else:
        return list(set(fibs))
