import hashlib
import random
from string import ascii_letters

def random_suffix():
    return ''.join(random.choice(ascii_letters) for _ in range(5))

def md5_file(filename):
    with open(filename, 'rb') as f:
        hasher = hashlib.md5()
        buf = f.read(65564)  # Read chunks up to 64KB
        while len(buf):
            hasher.update(buf)
            buf = f.read(65564)
        return hasher.hexdigest()

def generate_emails(filenames, suffixes=None):
    if not suffixes:
        suffixes = [random_suffix() for _ in filenames]
    domain = '@example.com'  # Replace with your desired domain
    emails = []
    for i, filename in enumerate(filenames):
        email = f""{filename}_{suffixes[i]}@{domain}""
        emails.append(email)
    return emails

def create_structures(doubles, strings):
    class CustomStruct:
        def __init__(self, d, s):
            self.d = d
            self.s = s

    data_structures = [CustomStruct(i*2.718, ''.join(random.choice(ascii_letters) for _ in range(5))) for i, (d, s) in enumerate(zip(doubles, strings))]
    return data_structures

def main():
    doubles = [i*3.14 for i in range(10)]  # Replace with your desired array of double values
    strings = ['file_{}'.format(i) for i in range(10)]  # Replace with your desired array of string filenames
    md5_hashes = [md5_file(f'data/{s}.txt') for s in strings]  # Change the path as needed
    emails = generate_emails(strings, [random_suffix() for _ in strings])
    data_structures = create_structures(doubles, emails)

if __name__ == ""__main__"":
    main()
