from xml.etree.ElementTree import parse
import CustomStack as cs

class ConfigurableCustomStack(cs.CustomStack):
    def __init__(self, config_filename):
        super().__init__()
        config_data = self.load_config(config_filename)
        self.tile_size, self.world_width, self.world_height, self.camera_speed = config_data

    @staticmethod
    def load_config(filename):
        if not os.path.isfile(filename):
            raise FileNotFoundError(f'Configuration file {filename} not found')
        with open(filename) as f:
            tree = parse(f)
            root = tree.getroot()
            return ConfigurableCustomStack.extract_config(root)

    @staticmethod
    def extract_config(root):
        tile_size = int(root.find('tile').attrib['size'])
        world_width = int(root.find('world').attrib['width'])
        world_height = int(root.find('world').attrib['height'])
        camera_speed = float(root.find('camera').attrib['speed'])
        return tile_size, world_width, world_height, camera_speed
```

