import xml.etree.ElementTree as ET
from typing import Union

def parse_xml(file_path: str, query: str) -> Union[list, dict]:
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()

        nodes = root.findall(query)

        if len(nodes) == 0:
            raise KeyError(f""No nodes found for query '{query}'"")

        if len(nodes) == 1:
            return nodes[0].text
        else:
            result = []
            for node in nodes:
                result.append(node.text)
            return result
    except FileNotFoundError:
        raise FileNotFoundError(f""File '{file_path}' not found"")
```

