0,"Create a Python script that defines a DataProcessor class with methods to read data from a CSV file, filter records based on specific criteria, and write the filtered data to a new CSV file. The filter_records method should accept parameters for the criteria to apply, such as date range or value thresholds, and return only the records that meet these conditions. The process_data method should utilize the filter_records method to clean the input data and then write the filtered records to an output CSV file. Additionally, include a function within the script that calculates and prints the total count of processed records and their average value based on specified columns in the input data.",589,,"[""```python
import csv
from typing import List, Tuple, Dict

class DataProcessor:
    def __init__(self):
        self.processed_records = []

    def read_csv(self, input_file: str) -> None:
        with open(input_file, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                self.processed_records.append(row)

    def filter_records(self, criteria: Dict[str, Union[str, int, List[int]]]) -> None:
        filtered_records = []
        for record in self.processed_records:
            matches = True
            for column, value in criteria.items():
                if isinstance(value, list):
                    if column not in record or not any(str(record[column]) not in str(v) for v in value):
                        matches = False
                        break
                else:
                    if column not in record or (isinstance(value, str) and value != record[column]) or (isinstance(value, int) and int(record[column]) != value):
                        matches = False
                        break
            if matches:
                filtered_records.append(record)
        self.processed_records = filtered_records

    def write_csv(self, output_file: str) -> None:
        with open(output_file, 'w', newline='') as csvfile:
            writer = csv.DictWriter(csvfile)
            writer.writeheader(next(csv.DictReader((iter([{'date':'dummy_date','value':'dummy_value'}])), skiprows=1)))
            for record in self.processed_records:
                writer.writerow(record)

    def process_data(self, input_file: str, output_file: str, criteria: Dict[str, Union[str, int, List[int]]]) -> None:
        self.read_csv(input_file)
        self.filter_records(criteria)
        self.write_csv(output_file)

    def calculate_stats(self, columns: List[str]) -> Tuple[int, float]:
        total = 0
        sum_values = 0
        for record in self.processed_records:
            total += 1
            for column in columns:
                if column in record:
                    value = int(record[column]) if column == 'id' else float(record[column])
                    sum_values += value
        avg_value = sum_values / total if total > 0 else 0.0
        return (total, avg_value)
```

