import hashlib
import sys
from statistics import mean
import argparse

def md5(data):
    return hashlib.md5(data.encode()).hexdigest()

def process_file(filename):
    with open(filename, 'r') as file:
        for line in file:
            elements = list(map(float, line.split()))
            if len(elements) < 2:
                continue
            print(f'MD5 of line: {md5(line)}')
            last_two = elements[-2:]
            mean_last_two = mean(last_two)
            print(f""Arithmetic mean of the last two elements: {mean_last_two}"")

def process_stdin():
    for line in sys.stdin:
        elements = list(map(float, line.split()))
        if len(elements) < 2:
            continue
        print(f'MD5 of line: {md5("""".join(line.split()))}')
        last_two = elements[-2:]
        mean_last_two = mean(last_two)
        print(f""Arithmetic mean of the last two elements: {mean_last_two}"")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(""file"", help=""Path to the input file"", type=str)
    args = parser.parse_args()

    if sys.stdin.isatty():  # Check if stdin is interactive
        process_stdin()
    else:
        process_file(args.file)

if __name__ == ""__main__"":
    main()
