This Python function `sum_primes_in_range` checks if the input is an integer and returns the sum of prime numbers within",327,,"[' ```python
import re

def sum_primes_in_range(number_range):
    # Check if input is an integer
    if not isinstance(number_range, int):
        raise ValueError(""Input must be an integer"")

    def is_prime(n):
        """"""Check if n is a prime number.""""""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Function to extract and count Bible Old Testament books from text
    def extract_books(text):
        old_testament_books = [
            ""Genesis"", ""Exodus"", ""Leviticus"", ""Numbers"", ""Deuteronomy"",
            ""Joshua"", ""Judges"", ""Ruth"", ""1 Samuel"", ""2 Samuel"",
            ""1 Kings"", ""2 Kings"", ""1 Chronicles"", ""2 Chronicles"",
            ""Ezra"", ""Nehemiah"", ""Esther"", ""Job"", ""Psalm""
        ]

        regex_pattern = r'\b(' + '|'.join(old_testament_books) + r')\b'
        regex = re.compile(regex_pattern)
        matches = regex.findall(text)

        book_counts = {}

        for book in matches:
            if book in book_counts:
                book_counts[book] += 1
            else:
                book_counts[book] = 1

        return book_counts

    # Main function logic
    primes_sum = 0

    for num in range(2, number_range + 1):
        if is_prime(num):
            primes_sum += num

    text_input = input(""Enter a string of text to extract Old Testament books: "")

    # Extract and count Old Testament books from user input
    extracted_books = extract_books(text_input)

    print(""Sum of prime numbers:"", primes_sum)

    # Display extracted books and their counts
    print(""\nOld Testament Books Mentioned:"")
    for book, count in extracted_books.items():
        print(f""{book}: {count} times"")
