2,"Create a Python script that accepts a list of URLs as input and concurrently downloads all the provided URLs using the `requests` library, returning a dictionary with the status codes of each download. If any URL fails to download, the function should return an error message indicating which URL encountered an issue.",78,,"['```python
import concurrent.futures
import requests
from urllib.parse import urlparse

def download_urls(url_list):
    status_codes = {}

    with concurrent.futures.ThreadPoolExecutor() as executor:
        failed_urls = []

        results = [executor.submit(download, url) for url in url_list]

        for result in results:
            try:
                status = result.result()
                status_codes[result.url] = status['status_code']
            except Exception as e:
                failed_urls.append(f""{result.url}: {e}"")

    if failed_urls:
        error_msg = ""\nError(s) occurred while downloading:\n"" + ""\n"".join(failed_urls)
        print(error_msg)

    return status_codes

def download(url):
    response = requests.get(url)

    if response.status_code not in [200, 301, 302]:
        raise Exception(f""Failed to download {url}. Status code: {response.status_code}"")

    return {'status_code': response.status_code}
