import random

def is_prime(num):
    if num < 2:
        return False
    for possible_divisor in range(2, int(num**0.5) + 1):
        if num % possible_divisor == 0:
            return False
    return True

def unique_primes(numbers, reverse=False):
    primes = [x for x in numbers if is_prime(x)]
    if reverse:
        return list(reversed(set(primes)))
    else:
        return set(primes)

