import sys
import os

OPTIONS = {
    'count': ""Count the number of lines in the input file"",
    'display': ""Display usage instructions and available options"",
}

def main(argv):
    if len(argv) < 4:
        print_usage()
        sys.exit(1)

    input_file = argv[1]
    operation = argv[2]
    output_file = argv[3]

    if not os.path.isfile(input_file):
        print(f""Error: '{input_file}' is not a valid file."")
        sys.exit(1)

    if operation == 'count':
        count_lines(input_file, output_file)
    elif operation == 'display':
        display_options()
    else:
        print(f""Error: Unknown operation '{operation}'."")
        sys.exit(1)

def count_lines(file_path, output_path):
    with open(file_path, 'r') as file:
        lines = file.readlines()

    with open(output_path, 'w') as file:
        file.write(str(len(lines)))

def display_options():
