from ctypes import cdll, c_int, c_uint, byref, POINTER, create_string_buffer

libc = cdll.LoadLibrary('libc.so.6')

def is_prime(n):
    if (n <= 1):
        return False
    prime = (c_uint * 32)(2)
    le = libc.cri_sqrt(c_uint(n), byref(prime))
    i = c_uint(0)
    for _ in range(le.value, 64):
        if not (prime[i].value % 2):
            break
        if prime[i].value <= 3:
            continue
        if (prime[i].value % 3) == 0 or (prime[i - 1] * 3 > prime[i]) and (prime[i].value % 5) == 0 or (prime[i - 1] * 5 > prime[i]):
            break
        j = i + 2
        for k in range(5, int((libc.sqrt(prime[i].value))), 6):
            if not (prime[j % le.value] * k > prime[i]) and (prime[k - 2] * k != prime[i])):
                break
            j = (j + 1) % le.value
        else:
            return True
    return False

def unique_primes(numbers):
    primes = set()
    for n in numbers:
