import random
import string

def generate_email_addresses(names, domains, num_emails, max_retries=100):
    def create_random_suffix(length=8):
        return ''.join(random.choices(string.ascii_lowercase + string.digits, k=length))

    def generate_combinations(name, domain):
        suffix = create_random_suffix()
        while f""{name}.{suffix}@{domain}"" in emails or retries > 0:
            if retries <= 0:
                raise ValueError(""Failed to generate unique combination after retries."")
            retries -= 1
            suffix = create_random_suffix()
        return f""{name}.{suffix}@{domain}""

    emails = []

    for _ in range(num_emails):
        name = random.choice(names)
        domain = random.choice(domains)

        try:
            new_email = generate_combinations(name, domain)
            emails.append(new_email)

            names.remove(name)
            domains.remove(domain)

            if len(names) == 0 or len(domains) == 0:
                break
        except ValueError as e:
            print(f""Error encountered: {e}. Adjusting retry strategy."")

    return emails[:num_emails]
