def generate_random_suffix():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=8))

def md5_hash(filepath):
    hash_obj = hashlib.md5()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hash_obj.update(chunk)
    return hash_obj.hexdigest()

def generate_emails(filename, suffix):
    domain = ""example.com""
    return {f'{filename}_{suffix}@{domain}', f'{filename}_{suffix}-alt@{domain}'}

def generate_data_structures(file_count, mem_block_size):
    doubles = [None] * mem_block_size
    labels = [''.join(random.choices(string.ascii_letters + string.digits, k=8)) for _ in range(mem_block_size)]
    data_structures = []
    for idx in range(file_count):
        doubles[idx] = (idx+1)**2
        data_structures.append(CustomDataStructure(doubles[idx], labels[idx]))
    return data_structures, doubles, labels

def main():
    input_dict = {}
    update_dict(input_dict, 'key1', 'value1')
    update_dict(input_dict, 'key2', 'value2')

    data_structures, doubles, labels = generate_data_structures(2, 5)

    directory = 'path/to/directory'

    emails = {}
    for filename in os.listdir(directory):
        if filename.endswith('.txt'):  # Modify this to include other supported file types
            hash_value = md5_hash(os.path.join(directory, filename))
            suffixes = generate_random_suffix()
            emails.update(generate_emails(filename, suffixes))

    for ds, hash_value, email in zip(data_structures, doubles, emails.values()):
        print(f'Data Structure: {ds}')
        print(f'Double Value: {ds.value}')
        print(f'Email Address: {email}')
        print('-' * 40)

if __name__ == ""__main__"":
    main()
