def prepare_data_for_visualization(df: pd.DataFrame) -> dict[str, list]:
    # Prepare data for visualization by converting the DataFrame into a dictionary with series names as keys and corresponding values as lists
    return df.to_dict('series')

def save_results(results: Union[pd.DataFrame, dict], file: str):
