import random
import string

def generate_passwords(names, charset_options, password_length):
    all_characters = {
        'uppercase': string.ascii_uppercase,
        'lowercase': string.ascii_lowercase,
        'digits': string.digits,
        'special': string.punctuation
    }

    passwords = {}

    for name in names:
        passwords[name] = []

    for i, option in enumerate(charset_options):
        characters = all_characters[option]
        for name in charset_options:
            if len(passwords[name]) < len(charset_options):
                password = ''.join(random.choice(characters) for _ in range(password_length))
                while password in [p for p in passwords[name] if name == passwords[name][p][0]]:
                    password = ''.join(random.choice(characters) for _ in range(password_length))
                passwords[name].append((name, password))

    return passwords
