import random

def generate_fibonacci_reverse(n, max_int):
    int_list = sorted(set([random.randint(1, max_int) for _ in range(n)]))

    fib_sequence = [0, 1]
    while fib_sequence[-1] < max(int_list):
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])

    filtered_fib = [fib for fib in fib_sequence if fib <= max(int_list)]

    return sorted(filtered_fib, reverse=True)
