The program should be structured with clear functions for each step, including reading CSV files, extracting emails, handling errors, managing resources efficiently, and displaying results or writing output as required.",590,,"['```python
import csv
import os
import logging
from typing import List, Set

def read_csv(filepath: str) -> Set[str]:
    emails = set()
    try:
        with open(filepath, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                if 'email' in row:
                    emails.add(row['email'])
    except Exception as e:
        logging.error(f""Error while processing {filepath}: {e}"")
    return emails

def process_files(filepaths: List[str]) -> (Set[str], List[str]):
    emails = set()
    errors = []
    for filepath in filepaths:
        emails.update(read_csv(filepath))

    return emails, errors

def main():
    logging.basicConfig(filename='error_log.txt', level=logging.ERROR)

    filepaths = ['data/file1.csv', 'data/file2.csv']  # Add more file paths as needed
    unique_emails, errors = process_files(filepaths)

    print(f""Total unique emails found: {len(unique_emails)}"")
    if errors:
        print(""Encountered errors during processing:"")
        for error in errors:
            print(error)

def write_output(emails: Set[str], output_file: str):
    with open(output_file, 'w', newline='') as csvfile:
        fieldnames = ['email']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for email in emails:
            writer.writerow({'email': email})

if __name__ == ""__main__"":
    main()
```

This code creates a Python program that reads multiple CSV files, extracts unique email addresses, handles errors, and displays the total count of unique email addresses found across all files. Optionally, it can also write the collected unique email addresses to a new CSV file for further use or analysis. The functions are well-structured and clearly named for easy understanding.']",0,[0],[],True,0,0,0,

