0,"Create a function ""DataMasking"" with inputs 'data', 'patterns', and 'replacement'. Replace patterns in 'data' with corresponding replacements, ensuring each pattern has a unique replacement string. Allow priority specification for each pair. Validate input vectors for matching lengths and string data types. Return error messages for inconsistencies.",680,,"['```python
def DataMasking(data, patterns, replacements):
    if not isinstance(data, str) or len(data) != len(patterns) != len(replacements):
        return ""Error: Input vectors do not match in length.""

    for i in range(len(patterns)):
        if patterns[i] in replacements and (i, patterns[i]) not in enumerate(zip(patterns, replacements))[1]:
            return ""Error: Replacement string for pattern '{}' already exists."".format(patterns[i])

    masked_data = data
    for pattern, replacement in zip(patterns, replacements):
        masked_data = masked_data.replace(pattern, replacement)

    return masked_data
