def generateEmailAddresses(filename, domain):
    md5 = hashlib.md5()
    with open(filename, ""rb"") as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            md5.update(chunk)
    email_hash = md5.hexdigest()
    return email_hash + ""@"" + domain

def merge_dict(dictionary, key_to_add, value_to_add):
    if key_to_add not in dictionary:
        dictionary[key_to_add] = value_to_add
    else:
        dictionary[key_to_add].append(value_to_add)

def generatePublicKeyAndEmail():
    rsa = RSA.generate(2048)
    public_key = rsa.publickey().exportKey()
    filename = get_random_bytes(16).hex() + "".txt""
    with open(filename, ""wb"") as f:
        f.write(public_key)
    email = generateEmailAddresses(filename, ""example.com"")
    return public_key, email
