def merge_dynamic_dictionary_updates(data, keyword, value):
    hasher = md5.new(str(keyword).encode('utf-8'))
    hash_key = hasher.hexdigest()

    if hash_key not in data:
        data[hash_key] = {keyword: value}
    else:
        data[hash_key][keyword] = value

    return data
