import os, tempfile
from PIL import Image
from io import BytesIO

class PacketCache:
    def __init__(self):
        self.ip_packets = []
        self.uploaded_files = {}
        self.cache_dir = None
        self.packet_counter = 0

    def set_cache_location(self, new_cache_dir: str):
        if not os.path.exists(new_cache_dir):
            os.makedirs(new_cache_dir)
        self.cache_dir = new_cache_dir

    def generate_random_packet(self) -> None:
        source_ip = '.'.join(str(random.randint(0, 255)) for _ in range(4))
        dest_ip = '.'.join(str(random.randint(0, 255)) for _ in range(4))
        protocol_num = random.randint(1, 254)
        packet_len = random.randint(60, 1476)

        ip_packet_struct = struct.pack('!IIBH', ip_address_to_int(source_ip), ip_address_to_int(dest_ip), protocol_num,
                                       packet_len)

        self.ip_packets.append({'source': source_ip,
                                'destination': dest_ip,
                                'protocol': protocol_num,
                                'length': packet_len})

    def verify_packet(self) -> bool:
        for packet in self.ip_packets:
            if ip_address_to_int(packet['source']) != int(packet['source']):
                return False
            if ip_address_to_int(packet['destination']) != int(packet['destination']):
                return False
            if packet['protocol'] < 1 or packet['protocol'] > 254:
                return False
            if not (60 <= packet['length'] <= 1476):
                return False

        return True

    def manage_memory(self) -> None:
        del self.ip_packets[:]

    def upload_file(self, file_name: str, file_data: bytes) -> None:
        if file_name in self.uploaded_files:
            return
        temp_file = tempfile.NamedTemporaryFile(dir=self.cache_dir, delete=False)
        with open(temp_file.name, 'wb') as f:
            f.write(file_data)
        self.uploaded_files[file_name] = temp_file.name

    def get_cached_file(self, file_name: str) -> bytes:
        if file_name not in self.uploaded_files:
            return None
        with open(self.uploaded_files[file_name], 'rb') as f:
            return f.read()
```

