    def connect(self):
        self.open_connections += 1

    def disconnect(self):
        if self.open_connections > 0:
            self.open_connections -= 1

    def start_transaction(self):
        self.transactions += 1

    def commit(self):
        if self.transactions > 0:
            self.transactions -= 1

    def rollback(self):
        if self.transactions > 0:
            self.transactions -= 1

