    def setUp(self):
        self.db_connection = MockDatabaseConnection()

    def test_product_crud_with_stock_management(self, product, quantity):
        self.assertLessEqual(quantity, 0, ""Out-of-stock management rule violation"")

        with self.assertRaises(Exception) as context:
            product.create(quantity)
        self.assertTrue(""out-of-stock"" in str(context.exception), ""Incorrect error message"")

        product.update(quantity=quantity + abs(quantity))

        with self.assertRaises(Exception) as context:
            product.delete()
        self.assertTrue(""not found"" in str(context.exception), ""Incorrect error message"")

    def test_order_processing_with_invalid_ids(self, order, invalid_id):
        with self.assertRaises(Exception) as context:
            order.read(invalid_id)
        self.assertTrue(f""Invalid order ID {invalid_id}"" in str(context.exception), ""Incorrect error message received"")

        invalid_data = {""quantity"": -5}
        with self.assertRaises(Exception) as context:
            order.create(**invalid_data)
        self.assertTrue(f""Negative quantity {invalid_data['quantity']}"" in str(context.exception), ""Incorrect error message received"")
