import random
import struct
import os
import hashlib

def ip_address_to_int(ip):
    return int('.'.join(ip.split('.')), 256)

class PacketCache:
    def __init__(self, cache_dir: str):
        self.ip_packets = []
        self.cache_dir = cache_dir
        self.packet_counter = 0

    def set_cache_location(self, new_cache_dir: str):
        self.cache_dir = new_cache_dir

    def generate_random_packet(self) -> None:
        source_ip = '.'.join(str(random.randint(0, 255)) for _ in range(4))
        dest_ip = '.'.join(str(random.randint(0, 255)) for _ in range(4))
        protocol_num = random.randint(1, 254)
        packet_len = random.randint(60, 1476)

        ip_packet_struct = struct.pack('!IIBH', ip_address_to_int(source_ip), ip_address_to_int(dest_ip), protocol_num,
                                       packet_len)

        packet_hash = hashlib.sha256(ip_packet_struct).hexdigest()

        self.ip_packets.append({
            'source': source_ip,
            'destination': dest_ip,
            'protocol': protocol_num,
            'length': packet_len,
            'hash': packet_hash})

    def verify_packet(self) -> bool:
        if not os.path.exists(self.cache_dir):
            return False

        for packet in self.ip_packets:
            path_to_check = os.path.join(self.cache_dir, f'{packet[""hash""]}.pkt')
            if not os.path.exists(path_to_check):
                return False

            with open(path_to_check, 'rb') as f:
                loaded_packet_struct = f.read()

                if len(loaded_packet_struct) != struct.calcsize('!IIBH'):
                    return False

                unpacked_values = struct.unpack('!IIBH', loaded_packet_struct)
                unpacked_source_ip, unpacked_dest_ip, unpacked_protocol_num, _ \
                    = unpacked_values

                if int(unpacked_source_ip) != packet['source']:
                    return False

                if int(unpacked_dest_ip) != packet['destination']:
                    return False

                if unpacked_protocol_num != packet['protocol']:
                    return False

        return True

    def manage_memory(self) -> None:
        del self.ip_packets[:]

    def cache_packets(self) -> None:
        for packet in self.ip_packets:
            path_to_save = os.path.join(self.cache_dir, f'{packet[""hash""]}.pkt')
            with open(path_to_save, 'wb') as f:
                f.write(struct.pack('!IIBH', packet['source'], packet['destination'], packet['protocol'],
                                    packet['length']))
