import pandas as pd
from base64 import b64decode, b64encode
from CryptoJS import AES

def decrypt_aes(data, key):
    ciphertext = data.encode('utf-8')
    return AES.new(key, AES.MODE_CBC, iv=AES.randomKey()).decrypt(ciphertext)

def load_csv_with_encrypted_data(filepath):
    with open(filepath, 'r') as file:
        encrypted_data = file.read().split('\n')
    decrypted_data = [decrypt_aes(d, key).decode('utf-8') for d in encrypted_data]
    return pd.read_csv(pd.StringIO(""\n"".join(decrypted_data)))
```

