from typing import TypeVar, Callable, Dict, Any
import json

T = TypeVar('T')

class JsonParser:
    def __init__(self):
        self.registry = {}
        self.register_factory(""base"", lambda data: JsonBase(data))

    def register_factory(self, id: str, factory: Callable[[Dict], T]):
        self.registry[id] = factory

    def register_parser_extension(self, extension: 'JsonParserExtension'):
        self.parser_extensions.append(extension)

    def parse(self, json_str: str) -> T:
        try:
            data = json.loads(json_str)
            for ext in self.parser_extensions:
                data = ext.process(data)
            return self.registry[""base""](data)
        except json.JSONDecodeError:
            raise ValueError(""Invalid JSON string"")

    def generate(self) -> str:
        internal_data = {""key"": ""value""}
        return json.dumps(self.registry[""base""](internal_data))

class JsonBase(JsonParser):
    def to_json(self) -> str:
        return super().generate()

class CustomClass(CustomClassExtension, JsonParser):
    def register_factory(self, id: str, factory: Callable[[Dict], T]):
        super().register_factory(id, lambda data: {
            ""type"": ""custom"",
            ""payload"": factory(data)
        })

    def __init__(self):
        super().__init__()

