import csv
import email.utils
import logging
import os
from typing import List

def read_csv(filepath: str) -> list[str]:
    try:
        with open(filepath, newline='') as f:
            reader = csv.reader(f)
            emails = set()
            for row in reader:
                if len(row) > 1:
                    try:
                        email = email.utils.parseaddr(row[1])[1]
                        emails.add(email)
                    except Exception as e:
                        logging.error(f'Error parsing email from row {row}: {e}')
            return list(emails)
    except FileNotFoundError:
        logging.error(f""File not found: {filepath}"")
    except Exception as e:
        logging.error(f""Error reading file {filepath}: {e}"")
    return []

def main(csv_paths: List[str], output_file: str = None):
    email_list = set()
    logging.basicConfig(level=logging.ERROR, format='%(message)s')

    for csv_path in csv_paths:
        emails = read_csv(csv_path)
        email_list.update(emails)

    total_count = len(email_list)
    if output_file:
        with open(output_file, 'w', newline='') as f:
            writer = csv.writer(f)
            for email in sorted(email_list):
                writer.writerow([email])

    print(f'Found {total_count} unique emails across all files.')

if __name__ == '__main__':
    csv_files = ['file1.csv', 'file2.csv']  # list of CSV file paths
    main(csv_files, 'output.csv')           # optional output file path
