This integrated solution aims to enhance data management by ensuring emails are securely generated and efficiently organizing files through automatic extension modifications, simplifying complex data processing tasks across different platforms with Python's randomization capabilities combined with C's powerful string manipulation techniques.",680,,"['```python
import string
import random
import re

def generate_random_email_and_rename_files(name_domains, filenames):
    emails = {}
    email_pattern = r""(\w+)@(\w+\.)+\w+""

    for name_domain in name_domains:
        email = f'{name_domain[0]}.{random_suffix}@{name_domain[1]}'
        random_suffix = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(5))
        emails[email] = True

    file_extensions = {'txt': 0, 'docx': 0, 'pdf': 0}

    for filename in filenames:
        match = re.search(email_pattern, filename)
        if match:
            email = match[0]
            if email not in emails:
                print(f'Email {email} is not unique')
            else:
                continue

        # Extract digits and calculate the number of digits before they repeat
        digit_pattern = r'\d+'
        digits = re.findall(digit_pattern, filename)
        if not digits:
            extension = ''
        else:
            current_num = int(digits[0])
            repeating_index = len(digits) - 1
            while repeating_index > 0 and int(digits[repeating_index]) == current_num:
                repeating_index -= 1
            num_digits = len(digits[:repeating_index + 1])
            extension = f'.{num_digits}{filename[-4:]}' if num_digits < 5 else '.pdf'

        # Modify the file extension and update the file_extensions data structure
        new_filename = re.sub(digit_pattern, '', filename) + extension
        print(f'Renamed {filename} to {new_filename}')
        for ext, count in file_extensions.items():
            if new_filename.endswith(ext):
                file_extensions[ext] += 1
            else:
                file_extensions[ext] = count + 1

    return emails, file_extensions
