        password += [random.choice(string.digits + string.punctuation) for _ in range(random.randint(2, length))]

        # Check if password meets minimum requirements
        if len(set(password)) == length and any(isupper(c) for c in password) and any(isdigit(c) for c in password) and any(c in string.punctuation for c in password):
            strength_met = True

    return ''.join(password)

def main():
    words = []
    while True:
        word = input(""Enter a word to create a password, or type 'done' to save and exit: "").lower()

        if word == 'done':
            break

        try:
            generated_password = generate_password(word)
            words.append((word, generated_password))
            print(""Generated password:"", generated_password)
        except ValueError as e:
            print(e)

    with open('passwords.txt', 'w') as f:
        for word_pair in words:
            f.write(f""{word_pair[0]}: {word_pair[1]}\n"")

if __name__ == ""__main__"":
    main()
```

This script generates secure passwords based on the given criteria and saves them in a text file named 'passwords.txt'. Users can input words to create passwords, or type 'done' to save the generated passwords and exit the program. The password generation function ensures that the passwords meet certain strength requirements (minimum length, presence of uppercase and lowercase letters, numbers, and special characters).']",346,[0],[],True,0,0,0,

