import os
import requests
import json
from socket import gaierror

def resolve_domain(domain):
    try:
        response = requests.get(f'https://api.ipify.org?format=json')
        ip_address = response.json()['ip'] if response.status_code == 200 else None
        return ip_address if domain in [*map(lambda x: x[0], json.loads(response.content).get('as', []))] else None
    except (requests.exceptions.RequestException, gaierror) as e:
        print(f""Error resolving domain: {e}"")
        return None

def isValidTokenResponse(jsonStr):
    try:
        json.loads(jsonStr)
        return True
    except ValueError:
        print(""Invalid JSON response"")
        return False

def processFileContent(filename):
    lines = []
    with open(filename, 'r') as file:
        for line in file:
            lines.append(line.strip())
    if not lines:
        print(""Error opening or reading the file"")
        return None
    return lines

