    for line in lines:
        # Perform HTTP requests using the resolved IP address, update/delete resources based on user input and API responses
        response = requests.get(f'http://{ip_address}/api', params={'data': json.dumps({""command"": line})})

        if not isValidTokenResponse(response.content):
            print(""Error in API interaction"")
            exit()

        response_json = json.loads(response.content)
        if int(resource_id) == response_json['resource_id']:
            if line.startswith('update'):
                updated_data = eval(line[6:]) # Extract updated data from the command
                update_resource(resource_id, updated_data)
            elif line.startswith('delete'):
                delete_resource(resource_id)

    print(""Process completed successfully!"")
